12	    /// A `describe` block should not contain duplicate hooks.
13	    ///
14	    /// ## Examples
15	    ///
16	    /// ### Invalid
17	    ///
18	    /// ```js,expect_diagnostic
19	    /// describe('foo', () => {
20	    ///   beforeEach(() => {
21	    ///     // some setup
22	    ///   });
23	    ///   beforeEach(() => {
24	    ///     // some setup
25	    ///   });
26	    ///   test('foo_test', () => {
27	    ///    // some test
28	    ///   });
29	    /// });
30	    /// ```
31	    ///
32	    /// ```js,expect_diagnostic
33	    /// describe('foo', () => {
34	    ///   beforeEach(() => {
35	    ///     // some setup
36	    ///   });
37	    ///   test('foo_test', () => {
38	    ///     afterAll(() => {
39	    ///       // some teardown
40	    ///     });
41	    ///    afterAll(() => {
42	    ///      // some teardown
43	    ///    });
44	    ///   });
45	    /// });
46	    /// ```
47	    ///
48	    /// ### Valid
49	    ///
50	    /// ```js
51	    /// describe('foo', () => {
52	    ///   beforeEach(() => {
53	    ///     // some setup
54	    ///   });
55	    ///   test('foo_test', () => {
56	    ///     // some test
57	    ///   });
58	    /// });
59	    /// ```
60	    ///
61	    pub NoDuplicateTestHooks {
62	        version: "1.6.0",
63	        name: "noDuplicateTestHooks",
64	        language: "js",
65	        recommended: true,
66	        severity: Severity::Error,
67	        sources: &[
68	            RuleSource::EslintJest("no-duplicate-hooks").inspired(),
69	            RuleSource::EslintVitest("no-duplicate-hooks").inspired(),
70	        ],
71	        domains: &[RuleDomain::Test],
72	    }
73	}
